(7721633, 1271042, 100831, '<td valign="top">... best place in the world to while away the time.</td>', '... best place in the world to while away the time.', '2022-06-15 12:17:35.000000', NULL, 1),
(7721634, 1271035, 100831, '<td valign="top">of course!</td>', 'of course!', '2022-06-15 12:18:38.000000', NULL, 1),
(7721635, 1270997, 100831, '<td valign="top">what a perspective... and way to relax!</td>', 'what a perspective... and way to relax!', '2022-06-15 12:20:14.000000', NULL, 1),
(7721636, 1271044, 100831, '<td valign="top">Funny, and great idea for the challenge, can''t say I love the processing here though.</td>', 'Funny, and great idea for the challenge, can''t say I love the processing here though.', '2022-06-15 12:21:28.000000', NULL, 1),
(7721644, 1271011, 30861, '<td valign="top">This is completely irrelevant, but just so you know I absolutely HATE magnetic darts :-) I mean, c''mon, the whole THING about darts is to have a legitimate reason to hurl pointy objects around :-)</td>', 'This is completely irrelevant, but just so you know I absolutely HATE magnetic darts :-) I mean, c''mon, the whole THING about darts is to have a legitimate reason to hurl pointy objects around :-)', '2022-06-15 17:05:59.000000', NULL, 1),
(7721645, 1270794, 30861, '<td valign="top">That is WEIRD :-) Is the dog''s very long leashed staked into the sand on a spike? Never seen the like :-) I suppose it makes some sort of sense but it certainly breaks any normal "leash laws" in that the dog''s not controllable... Anyway, cool pic :-)</td>', 'That is WEIRD :-) Is the dog''s very long leashed staked into the sand on a spike? Never seen the like :-) I suppose it makes some sort of sense but it certainly breaks any normal "leash laws" in that the dog''s not controllable... Anyway, cool pic :-)', '2022-06-15 17:08:02.000000', NULL, 1),
(7721646, 1270975, 30861, '<td valign="top">I''m not sure I''d call this sort of mountain hiking a "trivial pursuit", actually, but based on what I''m seeing in the challenge a LOT of people think worthwhile, healthy, active things qualify as "trivial" :-) Anyway, it''s a lovely place/picture, Margaret. I wish I were well enough to do this :-(</td>', 'I''m not sure I''d call this sort of mountain hiking a "trivial pursuit", actually, but based on what I''m seeing in the challenge a LOT of people think worthwhile, healthy, active things qualify as "trivial" :-) Anyway, it''s a lovely place/picture, Margaret. I wish I were well enough to do this :-(', '2022-06-15 17:18:41.000000', NULL, 1),
(7721647, 1270820, 30861, '<td valign="top">How DARE you call Gordon trivial!!!! Jejeje...</td>', 'How DARE you call Gordon trivial!!!! Jejeje...', '2022-06-15 17:19:30.000000', NULL, 1),
(7721648, 1271019, 30861, '<td valign="top">Is that for real, or are you (gasp) faking it for effect? Either way, good one.</td>', 'Is that for real, or are you (gasp) faking it for effect? Either way, good one.', '2022-06-15 17:22:00.000000', NULL, 1),
